            98 => ['A sertés rostélyost kiklopfoljuk, sózzuk, borsozzuk.', 'A hagymát vékony karikákra vágjuk.', 'Serpenyőben kevés olajon a húst elkezdjük sütni.', 'Amikor az egyik oldala megsült, megfordítjuk, és mellédobjuk a hagymakarikákat.', 'A hagymát aranybarnára pirítjuk, közben a hús is megsül.', 'A pirított hagymával a hús tetején, sült burgonyával tálaljuk.'],
            99 => ['A tojássárgáját cukorral habosra keverjük, majd hozzáadjuk a mascarponét, simára keverjük.', 'A kávét lefőzzük, kihűtjük.', 'A piskótát rövid időre a kávéba mártogatjuk, majd egy tál aljára fektetjük.', 'A kávés piskótára mascarponés krémet kenünk, friss eperszeleteket teszünk rá.', 'A rétegezést addig ismételjük, amíg a hozzávalók el nem fogynak.', 'Hűtőben legalább 4 órát pihentetjük, kakaóporral megszórva tálaljuk.'],
            100 => ['A tojásokat felverjük, sózzuk, borsozzuk.', 'A paprikát és paradicsomot megmossuk, felkockázzuk.', 'Serpenyőben kevés olajat forrósítunk, beletesszük a zöldségeket, megpirítjuk.', 'Ráöntjük a felvert tojásokat, reszelt sajttal megszórjuk.', 'Amikor a tojás alja megszilárdult, az omlettet félbehajtjuk.', 'Mindkét oldalát aranybarnára sütjük, friss kenyérrel tálaljuk.'],
        ];

        $records = [];
        foreach ($recipeSteps as $recipeId => $steps) {
            foreach ($steps as $order => $description) {
                $records[] = [
                    'description' => $description,
                    'recipe_id' => $recipeId,
                    'order' => $order + 1,
                ];
            }
        }

        foreach (array_chunk($records, 100) as $chunk) {
            DB::table('step')->insert($chunk);
        }
    }
